function minOperations(nums) {
  const n = nums.length;
  const unique = [...new Set(nums)].sort((a, b) => a - b);
  let right = 0;
  let keep = 0;

  for (let left = 0; left < unique.length; left++) {
    while (right < unique.length && unique[right] <= unique[left] + n - 1) {
      right++;
    }
    keep = Math.max(keep, right - left);
  }
  return n - keep;
}

