function minOperations(nums) {
  // Some best target run can start at a value already in nums; try each and count what fits.
  let best = nums.length;
  for (const start of nums) {
    const inside = new Set(nums.filter(v => v >= start && v < start + nums.length));
    best = Math.min(best, nums.length - inside.size);
  }
  return best;
}

